const text = output.toLowerCase();
const nums = (output.replace(/[,$]/g, ' ').match(/(?<![\w.])-?\d+(?:\.\d+)?(?!\w)/g) || []).map(Number);
const checks = [{"type":"ids","want":["NVIDIA A100 80GB PCIe"]},{"type":"number","value":2.09,"tol":0.005}];
const missing = checks.filter((c) =>
  c.type === 'number' ? !nums.some((n) => Math.abs(n - c.value) <= c.tol + 1e-9)
  : c.type === 'ids' ? !c.want.every((id) => text.includes(id.toLowerCase()))
  : !c.anyOf.some((p) => text.includes(p.toLowerCase())));
return missing.length === 0 ? true : { pass: false, score: 0, reason: 'missing ' + JSON.stringify(missing) };

